# Generated by build.py from recipe.yml for recipe amqp-keep-a-queue-across-restarts. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--directory', 'data', '--allow-anonymous', '--queue', '"jobs;durable"', '--queue', 'scratch', 'amqp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS -d job-1 amqp://127.0.0.1:8080/%2F/jobs --next -sS -d job-2 amqp://127.0.0.1:8080/%2F/jobs --next -sS -d job-3 amqp://127.0.0.1:8080/%2F/jobs --next -sS -d tmp amqp://127.0.0.1:8080/%2F/scratch
curl.exe -sS -d job-1 amqp://127.0.0.1:8081/%2F/jobs --next -sS -d job-2 amqp://127.0.0.1:8081/%2F/jobs --next -sS -d job-3 amqp://127.0.0.1:8081/%2F/jobs
curl.exe -sS -o NUL amqp://127.0.0.1:8080/%2F/jobs
try { curl.exe -sS amqp://127.0.0.1:8080/%2F/jobs } finally { Stop-Process $server0 }
